import os
import importlib.util
import math

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
celsius_to_fahrenheit = target.celsius_to_fahrenheit


def test_zero_celsius():
    # 0 * 9/5 + 32 = 32.0
    assert celsius_to_fahrenheit(0) == 32.0


def test_100_celsius():
    # 100 * 9/5 + 32 = 212.0
    assert celsius_to_fahrenheit(100) == 212.0


def test_37_celsius():
    # 37 * 9/5 + 32 = 98.6
    assert celsius_to_fahrenheit(37) == 98.6


def test_36_5_celsius():
    # 36.5 * 9/5 + 32 = 97.7
    assert celsius_to_fahrenheit(36.5) == 97.7


def test_negative_celsius():
    # -40 * 9/5 + 32 = -40.0
    assert celsius_to_fahrenheit(-40) == -40.0


def test_integer_input():
    # int should be accepted as numeric
    assert celsius_to_fahrenheit(0) == 32.0
    assert celsius_to_fahrenheit(100) == 212.0


def test_string_input_raises_type_error():
    try:
        celsius_to_fahrenheit("hello")
        assert False, "Expected TypeError"
    except TypeError:
        pass


def test_none_input_raises_type_error():
    try:
        celsius_to_fahrenheit(None)
        assert False, "Expected TypeError"
    except TypeError:
        pass


def test_list_input_raises_type_error():
    try:
        celsius_to_fahrenheit([1, 2])
        assert False, "Expected TypeError"
    except TypeError:
        pass


def test_half_degree_rounding():
    # 36.666... * 9/5 + 32 = 98.0 (36 2/3 celsius)
    result = celsius_to_fahrenheit(36.666666666666664)
    assert result == 98.0


def test_small_fractional():
    # 0.5 * 9/5 + 32 = 0.9 + 32 = 32.9
    assert celsius_to_fahrenheit(0.5) == 32.9


def test_rounding_one_decimal():
    # 25 * 9/5 + 32 = 45 + 32 = 77.0
    assert celsius_to_fahrenheit(25) == 77.0


def test_result_is_float():
    result = celsius_to_fahrenheit(0)
    assert isinstance(result, float)


def test_large_negative():
    # -100 * 9/5 + 32 = -180 + 32 = -148.0
    assert celsius_to_fahrenheit(-100) == -148.0

